export const ALIENS=[{id:"heatblast",name:"Heatblast",species:"Pyronite",homePlanet:"Pyros",abilities:["Fire manipulation","Flight (limited)","Heat resistance"],summary:"Heatblast is a blazing Pyronite composed of living magma. He hurls fireballs, rides jets of flame to stay airborne, and shrugs off extreme temperatures. Though hot-headed, he protects others by absorbing dangerous heat and excels at flashy, high-energy combat.",firstAppearance:"Season 1, Episode 1 — 'And Then There Were 10'",img:"assets/img/heatblast.webp",powerLevel:8,unlockedBy:"Original Omnitrix",},{id:"xlr8",name:"XLR8",species:"Kineceleran",homePlanet:"Kinet",abilities:["Supersonic speed","Enhanced reflexes","Electro-kinetic claws"],summary:"XLR8 is a sleek, velociraptor-like sprinter who can top hundreds of miles per hour in seconds. His taloned wheels grip almost any surface, granting incredible cornering and acrobatics. He relies on speed and wit to outmaneuver foes and control chaotic situations.",firstAppearance:"Season 1, Episode 1 — 'And Then There Were 10'",img:"assets/img/xlr8.webp",powerLevel:9,unlockedBy:"Original Omnitrix",},{id:"diamondhead",name:"Diamondhead",species:"Petrosapien",homePlanet:"Petropia",abilities:["Crystal generation","Energy refraction","Regeneration"],summary:"Diamondhead is a crystalline warrior whose body refracts energy and forms indestructible blades, shields, and projectiles. He reshapes his limbs on the fly, absorbs laser blasts, and crafts dazzling defenses, making him a reliable powerhouse in protracted battles.",firstAppearance:"Season 1, Episode 1 — 'And Then There Were 10'",img:"assets/img/diamondhead.webp",powerLevel:8,unlockedBy:"Original Omnitrix",},{id:"four-arms",name:"Four Arms",species:"Tetramand",homePlanet:"Khoros",abilities:["Super strength","Shockwave generation","Enhanced durability"],summary:"Four Arms towers with quadruple limbs and devastating muscle. He leaps city blocks, slams fists together to unleash shockwaves, and tank hits that would crush a truck. Despite brute force, he stays level-headed and protects bystanders before throwing punches.",firstAppearance:"Season 1, Episode 1 — 'And Then There Were 10'",img:"assets/img/four-arms.webp",powerLevel:9,unlockedBy:"Original Omnitrix",},{id:"grey-matter",name:"Grey Matter",species:"Galvan",homePlanet:"Galvan Prime",abilities:["Hyper-intelligence","Technopathy","Agility"],summary:"Grey Matter is a tiny Galvan with a colossal brain. He slips through vents, rewires alien tech on the spot, and devises improbable solutions. Though physically small, his creativity turns gadgets into victory tools and neutralizes threats with clever finesse.",firstAppearance:"Season 1, Episode 1 — 'And Then There Were 10'",img:"assets/img/grey-matter.webp",powerLevel:4,unlockedBy:"Original Omnitrix",},{id:"upgrade",name:"Upgrade",species:"Galvanic Mechamorph",homePlanet:"Galvan B",abilities:["Technological fusion","Energy beams","Adaptive armor"],summary:"Upgrade is a liquid-metal Mechamorph who fuses with machines, reconfiguring them into advanced forms. He fires neon energy beams, coats allies in protective plating, and adapts instantly to digital threats, making him a versatile hacker on the battlefield.",firstAppearance:"Season 1, Episode 2 — 'Washington B.C.'",img:"assets/img/upgrade.webp",powerLevel:7,unlockedBy:"Original Omnitrix",},{id:"wildmutt",name:"Wildmutt",species:"Vulpimancer",homePlanet:"Vulpin",abilities:["Enhanced senses","Razor-sharp claws","Acrobatic agility"],summary:"Wildmutt is a feral Vulpimancer with no eyes but heightened smell and echolocation. He bounds on powerful forelimbs, tears through armor with serrated claws, and tracks enemies across miles. Instinct guides him, delivering raw strikes in close quarters.",firstAppearance:"Season 1, Episode 2 — 'Washington B.C.'",img:"assets/img/wildmutt.webp",powerLevel:6,unlockedBy:"Original Omnitrix",},{id:"ghostfreak",name:"Ghostfreak",species:"Ectonurite",homePlanet:"Anur Phaetos",abilities:["Intangibility","Invisibility","Possession"],summary:"Ghostfreak is a chilling Ectonurite who phases through walls, vanishes into darkness, and manipulates shadows. His frightening visage and telepathic whispers unsettle opponents, while his ability to possess machinery turns battlefields into haunted traps.",firstAppearance:"Season 1, Episode 3 — 'The Krakken'",img:"assets/img/ghostfreak.webp",powerLevel:7,unlockedBy:"Original Omnitrix",},{id:"ripjaws",name:"Ripjaws",species:"Piscciss Volann",homePlanet:"Piscciss",abilities:["Aquatic adaptation","Bioluminescent lure","Powerful bite"],summary:"Ripjaws is an amphibious predator built for deep sea missions. He swims at torpedo speeds, breathes underwater indefinitely, and slices through steel with serrated jaws. Out of water he dehydrates quickly, but in aquatic arenas he dominates completely.",firstAppearance:"Season 1, Episode 4 — 'Permanent Retirement'",img:"assets/img/ripjaws.webp",powerLevel:6,unlockedBy:"Original Omnitrix",},{id:"stinkfly",name:"Stinkfly",species:"Lepidopterran",homePlanet:"Lepidopterra",abilities:["Flight","Slime projectiles","Prehensile tail"],summary:"Stinkfly is an insectoid aerial ace who zips through urban canyons with agile wings. He sprays corrosive slime, lashes foes with a flexible tail, and carries teammates across battlefields. His sharp vision and airborne agility make him an adaptable scout.",firstAppearance:"Season 1, Episode 5 — 'Hunted'",img:"assets/img/stinkfly.webp",powerLevel:5,unlockedBy:"Original Omnitrix",},];export const ALIENS_BY_ID=ALIENS.reduce((map,alien)=>{map[alien.id]=alien;return map;},{});